const fs = require("fs");
const path = require("path");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  let tw;
  try { tw = require("tailwindcss"); } catch (e) { broken("cannot load tailwindcss: " + e.message); }
  if (typeof tw.__unstable__loadDesignSystem !== "function") broken("__unstable__loadDesignSystem is missing");
  const dir = path.dirname(require.resolve("tailwindcss/package.json"));
  let ds;
  try {
    ds = await tw.__unstable__loadDesignSystem('@import "tailwindcss";', {
      base: dir,
      loadStylesheet: async (id) => {
        if (id !== "tailwindcss") broken("unexpected stylesheet " + id);
        const file = path.join(dir, "index.css");
        return { path: file, base: dir, content: fs.readFileSync(file, "utf8") };
      },
    });
  } catch (e) { broken("loadDesignSystem failed: " + e.message); }
  if (typeof ds.canonicalizeCandidates !== "function") broken("canonicalizeCandidates is missing");
  const input = "ml-[calc(-1*var(--width))]";
  const out = ds.canonicalizeCandidates([input]);
  if (!Array.isArray(out) || out.length !== 1 || typeof out[0] !== "string") broken("unexpected result " + JSON.stringify(out));
  if (out[0] === "-ml-(--width)") { console.log("OK: ml-[calc(-1*var(--width))] canonicalizes to -ml-(--width)"); return; }
  if (!out[0].startsWith("-")) symptom("canonicalizeCandidates kept the - sign inside the arbitrary value of ml-[calc(-1*var(--width))]");
  broken("ml-[calc(-1*var(--width))] canonicalized to " + out[0]);
})().catch((e) => broken(String(e && e.message)));

